import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int t = Integer.parseInt(br.readLine().trim());StringBuilder sb = new StringBuilder();while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());StringTokenizer st = new StringTokenizer(br.readLine());long[] a = new long[n];long gcdVal = 0;long sum = 0;for (int i = 0; i < n; i++) {a[i] = Long.parseLong(st.nextToken());sum += a[i];if (i == 0) gcdVal = a[i];else gcdVal = gcd(gcdVal, a[i]);}long result = (sum / gcdVal) - n;sb.append(result).append("\n");}System.out.print(sb.toString());}private static long gcd(long a, long b) {while (b != 0) {a %= b;long temp = a;a = b;b = temp;}return a;}}